import numpy as np, random, time, sys
from scipy import sparse
from scipy.sparse import linalg as spla
n=300; density=0.01; k=5
bad=0
t0=time.time();
for seed in range(1000):
    A=sparse.random(n,n,density=density,format='csr',data_rvs=np.random.randn, random_state=seed)
    try:
        vals, vecs=spla.eigs(A,k=k,v0=np.ones(n),ncv=20,maxiter=n*50)
    except Exception as e:
        bad+=1
print('bad',bad)
print('elapsed', time.time()-t0)
